			; CYBADD.bas 20: If dr = "" Then dr = "A"
			dw kw_strcmpeq, var_dr, str2
			dw kw_goto_iffalse_n, if1_1
			dw kw_strcpy, var_dr, str3
if1_1:

			; CYBADD.bas 21: dr = dr + ":"
