			; CYBADD.bas 25: Input "File (NAME.COM; Enter: done)"; f
			dw kw_printstrvar, str5
			dw kw_inputstr, var_f

			; CYBADD.bas 26: f = UCase$(Trim$(f))
			dw kw_strtrim, stmp0, var_f
			dw kw_strucase, stmp0, stmp0
			dw kw_strcpy, var_f, stmp0

			; CYBADD.bas 27: If f = "" Then Exit Do
