			dw kw_cpeqvl, tmp0, 0
			dw kw_goto_iffalse_n, if4_1
			dw kw_strcat, var_f, str7
if4_1:

			; CYBADD.bas 29: Input "Long name (one word; Enter: none)"; ln
			dw kw_printstrvar, str8
